import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int T = 1; // As per original code, T is always 1
        for (int t = 0; t < T; t++) {
            run(br);
        }
    }

    public static void run(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        double[] probs = new double[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            probs[i] = Double.parseDouble(st.nextToken());
        }

        for (int i = 0; i < n; i++) {
            if (Math.abs(probs[i]) < 1e-6) {
                System.out.print("0 ");
                continue;
            }
            int m = n - 1;
            int size = 1 << m;
            double[] dp = new double[size];
            double[] other_probs = new double[m];
            int idx = 0;
            for (int j = 0; j < n; j++) {
                if (j != i) {
                    other_probs[idx++] = probs[j];
                }
            }
            dp[0] = probs[i];
            double total_prob = dp[0];

            for (int mask = 1; mask < size; mask++) {
                double sumP = 0.0;
                double sumVal = 0.0;
                int count = 0;
                for (int t = 0; t < m; t++) {
                    if ((mask & (1 << t)) != 0) {
                        sumP += other_probs[t];
                        sumVal += other_probs[t] * dp[mask ^ (1 << t)];
                        count++;
                    }
                }
                dp[mask] = sumVal / (1 - sumP);
                if (count < k) {
                    total_prob += dp[mask];
                }
            }
            System.out.print(total_prob + " ");
        }
        System.out.println();
    }
}
